<?php $pageTitle='Calendar'; $activePage='calendar'; require_once __DIR__.'/includes/header.php'; $events=[]; foreach($pdo->query('SELECT id,name,due_date FROM projects WHERE due_date IS NOT NULL')->fetchAll() as $project){$events[]=['title'=>'Project · '.$project['name'],'start'=>$project['due_date'],'color'=>'#0B5ED7'];} foreach($pdo->query('SELECT id,title,due_date FROM tasks WHERE due_date IS NOT NULL')->fetchAll() as $task){$events[]=['title'=>'Task · '.$task['title'],'start'=>$task['due_date'],'color'=>'#6C757D'];} ?><div class="mb-4"><span class="section-kicker">Shared timeline</span><h2 class="mt-2">Calendar</h2><p class="text-muted mb-0">Deadlines and delivery moments in one place.</p></div><div class="panel"><div id="calendar"></div></div><link href="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{new FullCalendar.Calendar(document.getElementById('calendar'),{initialView:'dayGridMonth',height:650,headerToolbar:{left:'prev,next today',center:'title',right:'dayGridMonth,timeGridWeek'},events:<?= json_encode($events,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>}).render()});</script><?php require_once __DIR__.'/includes/footer.php'; ?>
